insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 1, 'No princípio criou Deus os céus e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 2, 'E a terra estava desordenada e vazia, e as trevas estavam sobre a face do abismo, e o Espírito de Deus se movia sobre a face das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 3, 'E disse Deus: Haja luz; e houve luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 4, 'E viu Deus que a luz era boa: e separou Deus a luz das trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 5, 'E chamou Deus à luz Dia, e às trevas chamou Noite: e foi a tarde e a manhã o primeiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 6, 'E disse Deus: Haja expansão em meio das águas, e separe as águas das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 7, 'E fez Deus a expansão, e separou as águas que estavam debaixo da expansão, das águas que estavam sobre a expansão: e foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 8, 'E chamou Deus à expansão Céus: e foi a tarde e a manhã, o dia segundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 9, 'E disse Deus: Juntem-se as águas que estão debaixo dos céus em um lugar, e descubra-se a porção seca; e foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 10, 'E chamou Deus à porção seca Terra, e à reunião das águas chamou Mares; e viu Deus que era bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 11, 'E disse Deus: Produza a terra erva verde, erva que dê semente; árvore de fruto que dê fruto segundo a sua espécie, que sua semente esteja nela, sobre a terra: e foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 12, 'E produziu a terra erva verde, erva que dá semente segundo sua natureza, e árvore que dá fruto, cuja semente está nele, segundo a sua espécie; e viu Deus que era bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 13, 'E foi a tarde e a manhã, o dia terceiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 14, 'E disse Deus: Haja luminares na expansão dos céus para separar o dia e a noite: e sejam por sinais, e para as estações, e para dias e anos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 15, 'E sejam por luminares na expansão dos céus para iluminar sobre a terra: e foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 16, 'E fez Deus os dois grandes luminares; o luminar maior para que exerça domínio no dia, e o luminar menor para que exerça domínio na noite; fez também as estrelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 17, 'E as pôs Deus na expansão dos céus, para iluminar sobre a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 18, 'E para exercer domínio no dia e na noite, e para separar a luz e as trevas: e viu Deus que era bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 19, 'E foi a tarde e a manhã, o dia quarto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 20, 'E disse Deus: Produzam as águas répteis de alma vivente, e aves que voem sobre a terra, na expansão aberta dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 21, 'E criou Deus as grandes criaturas marinhas, e toda coisa viva que anda arrastando, que as águas produziram segundo a sua espécie, e toda ave de asas segundo sua espécie: e viu Deus que era bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 22, 'E Deus os abençoou dizendo: Frutificai e multiplicai, e enchei as águas nos mares, e as aves se multipliquem na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 23, 'E foi a tarde e a manhã, o dia quinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 24, 'E disse Deus: Produza a terra seres viventes segundo a sua espécie, animais e serpentes e animais da terra segundo sua espécie: e foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 25, 'E fez Deus animais da terra segundo a sua espécie, e gado segundo a sua espécie, e todo animal que anda arrastando sobre a terra segundo sua espécie: e viu Deus que era bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 26, 'E disse Deus: Façamos ao ser humano à nossa imagem, conforme nossa semelhança; e domine os peixes do mar, e as aves dos céus, e os animais, e toda a terra, e todo animal que anda arrastando sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 27, 'E criou Deus o ser humano à sua imagem, à imagem de Deus o criou; macho e fêmea os criou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 28, 'E Deus os abençoou; e disse-lhes Deus: Frutificai e multiplicai, e enchei a terra, e subjugai-a, e dominai os peixes do mar, as aves dos céus, e todos os animais que se movem sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 29, 'E disse Deus: Eis que vos dei toda erva que dá semente, que está sobre a face de toda a terra; e toda árvore em que há fruto de árvore que dá semente, vos será para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 30, 'E a todo animal da terra, e a todas as aves dos céus, e a tudo o que se move sobre a terra, em que há vida, toda erva verde lhes será para comer: e foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 1, 31, 'E viu Deus tudo o que havia feito, e eis que era bom em grande maneira. E foi a tarde e a manhã, o dia sexto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 1, 'E foram concluídos os céus e a terra, e tudo o que neles há.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 2, 'E acabou Deus no dia sétimo sua obra que fez, e repousou o dia sétimo de toda sua obra que havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 3, 'E abençoou Deus ao dia sétimo, e o santificou, porque nele repousou de toda sua obra que havia Deus criado e feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 4, 'Estas são as origens dos céus e da terra quando foram criados, no dia que o SENHOR Deus fez a terra e os céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 5, 'E antes que toda planta do campo existisse na terra, e antes que toda erva do campo nascesse; porque ainda não havia o SENHOR Deus feito chover sobre a terra, nem havia homem para que lavrasse a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 6, 'Mas subia da terra um vapor, que regava toda a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 7, 'Formou, pois, o SENHOR Deus ao homem do pó da terra, e assoprou em seu nariz sopro de vida; e foi o homem em alma vivente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 8, 'E havia o SENHOR Deus plantado um jardim em Éden ao oriente, e pôs ali ao homem que havia formado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 9, 'E havia o SENHOR Deus feito nascer da terra toda árvore agradável à vista, e boa para comer: também a árvore da vida em meio do jardim, e a árvore do conhecimento do bem e do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 10, 'E saía de Éden um rio para regar o jardim, e dali se repartia em quatro ramificações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 11, 'O nome de um era Pisom: este é o que cerca toda a terra de Havilá, onde há ouro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 12, 'E o ouro daquela terra é bom; há ali também bdélio e pedra ônix.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 13, 'O nome do segundo rio é Giom; este é o que rodeia toda a terra de Cuxe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 14, 'E o nome do terceiro rio é Tigre; este é o que vai diante da Assíria. E o quarto rio é o Eufrates.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 15, 'Então o SENHOR Deus tomou o homem, e o pôs no jardim de Éden, para que o lavrasse e o guardasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 16, 'E mandou o SENHOR Deus ao homem, dizendo: De toda árvore do jardim comerás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 17, 'Mas da árvore do conhecimento do bem e do mal não comerás dela; porque no dia que dela comeres, morrerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 18, 'E disse o SENHOR Deus: Não é bom que o homem esteja só; farei para ele ajuda idônea para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 19, 'Formou, pois, o SENHOR Deus da terra todo animal do campo, e toda ave dos céus, e trouxe-os a Adão, para que visse como lhes havia de chamar; e tudo o que Adão chamou aos animais viventes, esse é seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 20, 'E pôs Adão nomes a todo animal e ave dos céus e a todo animal do campo: mas para Adão não achou ajuda que estivesse idônea para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 21, 'E o SENHOR Deus fez cair sonho sobre Adão, e ele adormeceu: então tomou uma de suas costelas, e fechou a carne em seu lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 22, 'E da costela que o SENHOR Deus tomou do homem, fez uma mulher, e trouxe-a ao homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 23, 'E disse Adão: Esta é agora osso de meus ossos, e carne de minha carne: esta será chamada Mulher, porque do homem foi tomada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 24, 'Portanto, deixará o homem a seu pai e a sua mãe, e se achegará à sua mulher, e serão uma só carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 2, 25, 'E estavam ambos nus, Adão e sua mulher, e não se envergonhavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 1, 'Porém a serpente era astuta, mais que todos os animais do campo que o SENHOR Deus havia feito. E ela disse à mulher: Deus vos disse: Não comais de toda árvore do jardim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 2, 'E a mulher respondeu à serpente: Do fruto das árvores do jardim podemos comer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 3, 'mas do fruto da árvore que está no meio do jardim, Deus disse: Não comereis dele, nem o tocareis, para que não morrais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 4, 'Então a serpente disse à mulher: Não morrereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 5, 'Mas Deus sabe que no dia que comerdes dele, vossos olhos serão abertos, e sereis como deuses, sabendo o bem e o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 6, 'E a mulher viu que a árvore era boa para se comer, agradável aos olhos, e árvore desejável para se obter conhecimento. E ela tomou de seu fruto, e comeu; e deu também ao seu marido com ela, e ele comeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 7, 'E foram abertos os olhos de ambos, e conheceram que estavam nus. Então coseram folhas de figueira, e fizeram para si aventais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 8, 'E ouviram a voz do SENHOR Deus, que passeava no jardim à brisa do dia; e o homem e sua mulher esconderam-se da presença do SENHOR Deus entre as árvores do jardim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 9, 'E o SENHOR Deus chamou ao homem, e lhe disse: “Onde estás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 10, 'E ele respondeu: “Ouvi tua voz no jardim, e tive medo, porque estava nu; e me escondi”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 11, 'E disse-lhe: “Quem te ensinou que estavas nu? Comeste da árvore de que te mandei que não comesses?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 12, 'E o homem respondeu: “A mulher que me deste por companheira me deu da árvore, e eu comi”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 13, 'Então o SENHOR Deus disse à mulher: “Por que fizeste isto?” E a mulher disse: “A serpente me enganou, e comi”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 14, 'E o SENHOR Deus disse à serpente: “Porque fizeste isto, maldita serás entre todos os animais selvagens e entre todos os animais do campo; sobre teu ventre andarás, e pó comerás todos os dias da tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 15, 'E porei inimizade entre ti e a mulher, e entre tua descendência e a descendência dela; esta te ferirá a cabeça, e tu lhe ferirás o calcanhar”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 16, 'E para a mulher disse: “Multiplicarei grandemente as tuas dores e teus sofrimentos de parto; com dor darás à luz filhos; e o teu desejo será para o teu marido, e ele te dominará”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 17, 'E ao homem disse: “Porque deste ouvidos à voz de tua mulher, e comeste da árvore de que te mandei dizendo, ‘Não comerás dela’, maldita será a terra por causa de ti; com dor comerás dela todos os dias da tua vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 18, 'Espinhos e cardos te produzirá, e comerás erva do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 19, 'No suor do teu rosto comerás o pão até que voltes à terra, porque dela foste tomado; porque pó és, e ao pó voltarás”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 20, 'E chamou o homem o nome de sua mulher, Eva; porquanto ela era mãe de todos o viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 21, 'E o SENHOR Deus fez ao homem e à sua mulher túnicas de peles, e os vestiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 22, 'E disse o SENHOR Deus: Eis que o homem é como um de Nos sabendo o bem e o mal; agora, pois, para que não estenda sua mão, e tome também da árvore da vida, e coma, e viva para sempre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 23, 'E tirou-o o SENHOR do jardim de Éden, para que lavrasse a terra de que foi tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 3, 24, 'Lançou, pois, fora ao homem, e pôs ao oriente do jardim de Éden querubins, e uma espada acesa que se revolvia a todos os lados, para guardar o caminho da árvore da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 1, 'E Adão conheceu a sua mulher Eva, a qual concebeu e deu à luz a Caim, e disse: Obtive um homem pelo SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 2, 'E depois deu à luz a seu irmão Abel. E foi Abel pastor de ovelhas, e Caim foi lavrador da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 3, 'E aconteceu, decorrendo o tempo, que Caim trouxe do fruto da terra uma oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 4, 'E Abel trouxe também dos primogênitos de suas ovelhas, e de sua gordura. E olhou o SENHOR com agrado a Abel e à sua oferta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 5, 'mas não olhou com bons olhos a Caim e à sua oferta. Caim irritou-se muito, e descaiu-lhe o semblante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 6, 'Então o SENHOR disse a Caim: Por que te irritaste, e por que o teu semblante descaiu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 7, 'Se bem fizeres, não serás aceito? E se não fizeres bem, o pecado está à porta; contra ti será o seu desejo, porém tu deves dominá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 8, 'Depois Caim falou a seu irmão Abel; e aconteceu que, estando eles no campo, Caim se levantou contra seu irmão Abel, e o matou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 9, 'E o SENHOR disse a Caim: Onde está teu irmão Abel? E ele respondeu: Não sei; sou eu guarda do meu irmão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 10, 'E ele lhe disse: Que fizeste? A voz do sangue do teu irmão clama a mim desde a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 11, 'Agora, pois, maldito sejas tu da terra que abriu sua boca para receber o sangue de teu irmão de tua mão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 12, 'Quando lavrares a terra, não te voltará a dar sua força: errante e fugitivo serás na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 13, 'E disse Caim ao SENHOR: Grande é minha iniquidade para ser perdoada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 14, 'Eis que me expulsas hoje da face da terra, e de tua presença me esconderei; e serei errante e fugitivo na terra; e sucederá que qualquer um que me achar, me matará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 15, 'E respondeu-lhe o SENHOR: Certo que qualquer um que matar a Caim, sete vezes será castigado. Então o SENHOR pôs sinal em Caim, para que não o ferisse qualquer um que o achasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 16, 'E saiu Caim de diante do SENHOR, e habitou na terra de Node, ao oriente de Éden.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 17, 'E conheceu Caim a sua mulher, a qual concebeu e deu à luz a Enoque: e edificou uma cidade, e chamou o nome da cidade do nome de seu filho, Enoque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 18, 'E a Enoque nasceu Irade, e Irade gerou a Meujael, e Meujael gerou a Metusael, e Metusael gerou a Lameque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 19, 'E tomou para si Lameque duas mulheres; o nome de uma foi Ada, e o nome da outra Zilá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 20, 'E Ada deu à luz a Jabal, o qual foi pai dos que habitam em tendas, e criam gados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 21, 'E o nome de seu irmão foi Jubal, o qual foi pai de todos os que manejam harpa e flauta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 22, 'E Zilá também deu à luz a Tubalcaim, feitor de toda obra de bronze e de ferro: e a irmã de Tubalcaim foi Naamá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 23, 'E disse Lameque a suas mulheres: Ada e Zilá, ouvi minha voz; Mulheres de Lameque, escutai meu dito: Que matei um homem por ter me ferido, E um rapaz por ter me golpeado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 24, 'Se sete vezes será vingado Caim, Lameque em verdade setenta vezes sete o será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 25, 'E conheceu de novo Adão à sua mulher, a qual deu à luz um filho, e chamou seu nome Sete: Porque Deus (disse ela) me substituiu outra descendência em lugar de Abel, a quem matou Caim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 4, 26, 'E a Sete também lhe nasceu um filho, e chamou seu nome Enos. Então os homens começaram a invocar o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 1, 'Este é o livro das gerações de Adão. No dia em que criou Deus ao ser humano, à semelhança de Deus o fez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 2, 'Macho e fêmea os criou; e os abençoou, e chamou o nome deles Adão, no dia em que foram criados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 3, 'E viveu Adão cento e trinta anos, e gerou um filho à sua semelhança, conforme sua imagem, e chamou seu nome Sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 4, 'E foram os dias de Adão, depois que gerou a Sete, oitocentos anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 5, 'E foram todos os dias que viveu Adão novecentos e trinta anos, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 6, 'E viveu Sete cento e cinco anos, e gerou a Enos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 7, 'E viveu Sete, depois que gerou a Enos, oitocentos e sete anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 8, 'E foram todos os dias de Sete novecentos e doze anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 9, 'E viveu Enos noventa anos, e gerou a Cainã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 10, 'E viveu Enos depois que gerou a Cainã, oitocentos e quinze anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 11, 'E foram todos os dias de Enos novecentos e cinco anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 12, 'E viveu Cainã setenta anos, e gerou a Maalalel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 13, 'E viveu Cainã, depois que gerou a Maalalel, oitocentos e quarenta anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 14, 'E foram todos os dias de Cainã novecentos e dez anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 15, 'E viveu Maalalel sessenta e cinco anos, e gerou a Jarede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 16, 'E viveu Maalalel, depois que gerou a Jarede, oitocentos e trinta anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 17, 'E foram todos os dias de Maalalel oitocentos noventa e cinco anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 18, 'E viveu Jarede cento e sessenta e dois anos, e gerou a Enoque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 19, 'E viveu Jarede, depois que gerou a Enoque, oitocentos anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 20, 'E foram todos os dias de Jarede novecentos e sessenta e dois anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 21, 'E viveu Enoque sessenta e cinco anos, e gerou a Matusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 22, 'E caminhou Enoque com Deus, depois que gerou a Matusalém, trezentos anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 23, 'E foram todos os dias de Enoque trezentos sessenta e cinco anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 24, 'Caminhou, pois, Enoque com Deus, e desapareceu, porque Deus o levou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 25, 'E viveu Matusalém cento e oitenta e sete anos, e gerou a Lameque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 26, 'E viveu Matusalém, depois que gerou a Lameque, setecentos e oitenta e dois anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 27, 'Foram, pois, todos os dias de Matusalém, novecentos e sessenta e nove anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 28, 'E viveu Lameque cento e oitenta e dois anos, e gerou um filho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 29, 'E chamou seu nome Noé, dizendo: Este nos aliviará de nossas obras, e do trabalho de nossas mãos, por causa da terra que o SENHOR amaldiçoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 30, 'E viveu Lameque, depois que gerou a Noé, quinhentos noventa e cinco anos: e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 31, 'E foram todos os dias de Lameque setecentos e setenta e sete anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 5, 32, 'E sendo Noé de quinhentos anos, gerou a Sem, Cam, e a Jafé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 1, 'E aconteceu que, quando começaram os homens a multiplicar-se sobre a face da terra, e lhes nasceram filhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 2, 'Vendo os filhos de Deus que as filhas dos homens eram belas, tomaram para si mulheres, escolhendo entre todas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 3, 'E disse o SENHOR: Não brigará meu espírito com o ser humano para sempre, porque certamente ele é carne: mas serão seus dias cento e vinte anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 4, 'Havia gigantes na terra naqueles dias, e também depois que entraram os filhos de Deus às filhas dos homens, e lhes geraram filhos: estes foram os valentes que desde a antiguidade foram homens de renome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 5, 'E o SENHOR viu que a maldade dos seres humanos era muita na terra, e que todo desígnio dos pensamentos dos seus corações era só mau continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 6, 'E o SENHOR se arrependeu de haver feito o ser humano na terra, e pesou-lhe em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 7, 'E disse o SENHOR: Apagarei os seres humanos que criei de sobre a face da terra, desde o ser humano até o animal, e até o réptil e as aves do céu; porque me arrependo de havê-los feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 8, 'Porém Noé achou favor aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 9, 'Estas são as gerações de Noé: Noé, homem justo, foi íntegro em suas gerações; Noé andava com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 10, 'E gerou Noé três filhos: a Sem, a Cam, e a Jafé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 11, 'Porém a terra se corrompeu diante de Deus, e a terra encheu-se de violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 12, 'E Deus olhou a terra, e eis que estava corrompida; porque toda carne havia corrompido seu caminho sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 13, 'E disse Deus a Noé: O fim de toda carne veio diante de mim; porque a terra está cheia de violência por causa deles; e eis que eu os destruirei com a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 14, 'Faze-te uma arca de madeira de gôfer: farás aposentos na arca e a selarás com betume por dentro e por fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 15, 'E desta maneira a farás: de trezentos côvados o comprimento da arca, de cinquenta côvados sua largura, e de trinta côvados sua altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 16, 'Uma janela farás à arca, e a acabarás a um côvado de elevação pela parte de cima: e porás a porta da arca a seu lado; e lhe farás piso abaixo, segundo e terceiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 17, 'E eu, eis que eu trago um dilúvio de águas sobre a terra, para destruir toda carne em que haja espírito de vida debaixo do céu; tudo o que há na terra morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 18, 'Mas estabelecerei meu pacto contigo, e entrarás na arca tu, e teus filhos e tua mulher, e as mulheres de teus filhos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 19, 'E de tudo o que vive, de toda carne, dois de cada espécie porás na arca, para que tenham vida contigo; macho e fêmea serão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 20, 'Das aves segundo sua espécie, e dos animais segundo sua espécie, de todo réptil da terra segundo sua espécie, dois de cada espécie entrarão contigo para que tenham vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 21, 'E toma contigo de toda comida que se come, e traga-a a ti; servirá de alimento para ti e para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 6, 22, 'E o fez assim Noé; fez conforme tudo o que Deus lhe mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 1, 'E o SENHOR disse a Noé: Entra tu e toda tua casa na arca porque a ti vi justo diante de mim nesta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 2, 'De todo animal limpo tomarás de sete em sete, macho e sua fêmea; mas dos animais que não são limpos, dois, macho e sua fêmea.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 3, 'Também das aves dos céus de sete em sete, macho e fêmea; para guardar em vida a descendência sobre a face de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 4, 'Porque passados ainda sete dias, eu farei chover sobre a terra quarenta dias e quarenta noites; e apagarei toda criatura que fiz de sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 5, 'E fez Noé conforme tudo o que lhe mandou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 6, 'E sendo Noé de seiscentos anos, o dilúvio das águas foi sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 7, 'E veio Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele à arca, por causa das águas do dilúvio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 8, 'Dos animais limpos, e dos animais que não eram limpos, e das aves, e de todo o que anda arrastando sobre a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 9, 'De dois em dois entraram a Noé na arca: macho e fêmea, como mandou Deus a Noé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 10, 'E sucedeu que ao sétimo dia as águas do dilúvio foram sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 11, 'No ano seiscentos da vida de Noé, no mês segundo, no dia dezessete do mês, naquele dia foram rompidas todas as fontes do grande abismo, e as comportas dos céus foram abertas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 12, 'E houve chuva sobre a terra quarenta dias e quarenta noites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 13, 'Neste mesmo dia entrou Noé, e Sem, e Cam e Jafé, filhos de Noé, a mulher de Noé, e as três mulheres de seus filhos com ele na arca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 14, 'Eles e todos os animais silvestres segundo suas espécies, e todos os animais mansos segundo suas espécies, e todo réptil que anda arrastando sobre a terra segundo sua espécie, e toda ave segundo sua espécie, todo pássaro, toda espécie de animal voador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 15, 'E vieram a Noé à arca, de dois em dois de toda carne em que havia espírito de vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 16, 'E os que vieram, macho e fêmea de toda carne vieram, como lhe havia mandado Deus: e o SENHOR lhe fechou a porta'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 17, 'E foi o dilúvio quarenta dias sobre a terra; e as águas cresceram, e levantaram a arca, e se elevou sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 18, 'E prevaleceram as águas, e cresceram em grande maneira sobre a terra; e andava a arca sobre a face das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 19, 'E as águas prevaleceram muito em extremo sobre a terra; e todos os montes altos que havia debaixo de todos os céus, foram cobertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 20, 'Quinze côvados em altura prevaleceram as águas; e foram cobertos os montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 21, 'E morreu toda carne que se move sobre a terra, tanto de aves como de gados, e de animais, e de todo réptil que anda arrastando sobre a terra, e todo ser humano:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 22, 'Tudo o que tinha fôlego de espírito de vida em suas narinas, de tudo o que havia na terra, morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 23, 'Assim foi destruída toda criatura que vivia sobre a face da terra, desde o ser humano até o animal, e os répteis, e as aves do céu; e foram apagados da terra; e restou somente Noé, e os que com ele estavam na arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 7, 24, 'E prevaleceram as águas sobre a terra cento e cinquenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 1, 'E lembrou-se Deus de Noé, e de todos os animais, selvagens e domésticos que estavam com ele na arca; e fez passar Deus um vento sobre a terra, e diminuíram as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 2, 'E se fecharam as fontes do abismo, e as comportas dos céus; e a chuva dos céus foi detida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 3, 'E voltaram-se as águas de sobre a terra, indo e voltando; e decresceram as águas ao fim de cento e cinquenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 4, 'E repousou a arca no mês sétimo, a dezessete dias do mês, sobre os montes de Ararate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 5, 'E as águas foram decrescendo até o mês décimo: no décimo, ao primeiro dia do mês, se revelaram os cumes dos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 6, 'E sucedeu que, ao fim de quarenta dias, abriu Noé a janela da arca que havia feito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 7, 'E enviou ao corvo, o qual saiu, e esteve indo e voltando até que as águas se secaram de sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 8, 'Enviou também de si à pomba, para ver se as águas se haviam retirado de sobre a face da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 9, 'E não achou a pomba onde sentar a planta de seu pé, e voltou-se a ele à arca, porque as águas estavam ainda sobre a face de toda a terra: então ele estendeu sua mão e recolhendo-a, a fez entrar consigo na arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 10, 'E esperou ainda outros sete dias, e voltou a enviar a pomba fora da arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 11, 'E a pomba voltou a ele à hora da tarde; e eis que trazia uma folha de oliveira tomada em seu bico; então Noé entendeu que as águas haviam se retirado de sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 12, 'E esperou ainda outros sete dias, e enviou a pomba, a qual não voltou já mais a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 13, 'E sucedeu que no ano seiscentos e um de Noé, no mês primeiro, ao primeiro do mês, as águas se enxugaram de sobre a terra e tirou Noé a cobertura da arca, e olhou, e eis que a face da terra estava enxuta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 14, 'E no mês segundo, aos vinte e sete dias do mês, se secou a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 15, 'E falou Deus a Noé dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 16, 'Sai da arca tu, a tua mulher, os teus filhos, e as mulheres dos teus filhos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 17, 'Todos os animais que estão contigo de toda carne, de aves e de animais e de todo réptil que anda arrastando sobre a terra, tirarás contigo; e vão pela terra, e frutifiquem, e multipliquem-se sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 18, 'Então saiu Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 19, 'Todos os animais, e todo réptil e toda ave, tudo o que se move sobre a terra segundo suas espécies, saíram da arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 20, 'E edificou Noé um altar ao SENHOR e tomou de todo animal limpo e de toda ave limpa, e ofereceu holocaustos sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 21, 'E percebeu o SENHOR cheiro suave; e o SENHOR disse em seu coração: Não voltarei mais a amaldiçoar a terra por causa do ser humano; porque o intento do coração do ser humano é mau desde sua juventude: nem voltarei mais a destruir todo vivente, como fiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 8, 22, 'Enquanto a terra durar, a sementeira e a colheita, o frio e calor, verão e inverno, dia e noite, não cessarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 1, 'E Deus abençoou Noé e seus filhos, e disse-lhes: Frutificai, e multiplicai, e enchei a terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 2, 'E vosso temor e vosso pavor será sobre todo animal da terra, e sobre toda ave dos céus, em tudo o que se mover na terra, e em todos os peixes do mar: em vossa mão são entregues.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 3, 'Tudo o que se move e vive vos será para mantimento: assim como os legumes e ervas, vos dei disso tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 4, 'Porém a carne com sua vida, que é seu sangue, não comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 5, 'Porque certamente exigirei o sangue de vossas vidas; da mão de todo animal o exigirei, e da mão do ser humano; da mão do homem seu irmão exigirei a vida do ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 6, 'O que derramar sangue humano, pelo ser humano seu sangue será derramado; porque à imagem de Deus o ser humano foi feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 7, 'Mas vós frutificai, e multiplicai-vos; procriai abundantemente na terra, e multiplicai-vos nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 8, 'E falou Deus a Noé e a seus filhos com ele, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 9, 'Eis que eu mesmo estabeleço meu pacto convosco, e com vossa descendência depois de vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 10, 'E com toda alma vivente que está convosco, de aves, de animais, e de toda fera da terra que está convosco; desde todos os que saíram da arca até todo animal da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 11, 'Estabelecerei meu pacto convosco, e não será mais exterminada toda carne com águas de dilúvio; nem haverá mais dilúvio para destruir a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 12, 'E disse Deus: Este será o sinal do pacto que estabeleço entre mim e vós e toda alma vivente que está convosco, por tempos perpétuos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 13, 'Meu arco porei nas nuvens, o qual será por sinal de aliança entre mim e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 14, 'E será que quando fizer vir nuvens sobre a terra, se deixará ver então meu arco nas nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 15, 'E me lembrarei do meu pacto, que há entre mim e vós e toda alma vivente de toda carne; e não serão mais as águas por dilúvio para destruir toda carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 16, 'E estará o arco nas nuvens, e o verei para me lembrar do pacto perpétuo entre Deus e toda alma vivente, com toda carne que há sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 17, 'Disse, pois, Deus a Noé: Este será o sinal do pacto que estabeleci entre mim e toda carne que está sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 18, 'E os filhos de Noé que saíram da arca foram Sem, Cam e Jafé: e Cam é o pai de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 19, 'Estes três são os filhos de Noé; e deles foi cheia toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 20, 'E começou Noé a lavrar a terra, e plantou uma vinha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 21, 'E bebeu do vinho, e se embriagou, e estava descoberto dentro de sua tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 22, 'E Cam, pai de Canaã, viu a nudez de seu pai, e disse-o aos seus dois irmãos do lado de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 23, 'Então Sem e Jafé tomaram a roupa, e a puseram sobre seus próprios ombros, e andando para trás, cobriram a nudez de seu pai tendo seus rostos virados, e assim não viram a nudez de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 24, 'E despertou Noé de seu vinho, e soube o que havia feito com ele seu filho o mais jovem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 25, 'E disse: Maldito seja Canaã; Servo de servos será a seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 26, 'Disse mais: Bendito o SENHOR o Deus de Sem, E seja-lhe Canaã servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 27, 'Engrandeça Deus a Jafé, E habite nas tendas de Sem, E seja-lhe Canaã servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 28, 'E viveu Noé depois do dilúvio trezentos e cinquenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 9, 29, 'E foram todos os dias de Noé novecentos e cinquenta anos; e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 1, 'Estas são as gerações dos filhos de Noé: Sem, Cam e Jafé, aos quais nasceram filhos depois do dilúvio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 2, 'Os filhos de Jafé: Gômer, e Magogue, e Madai, e Javã, e Tubal, e Meseque, e Tiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 3, 'E os filhos de Gômer: Asquenaz, e Rifate, e Togarma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 4, 'E os filhos de Javã: Elisá, e Társis, Quitim, e Dodanim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 5, 'Por estes foram repartidas as ilhas das nações em suas terras, cada qual segundo sua língua, conforme suas famílias em suas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 6, 'Os filhos de Cam: Cuxe, e Mizraim, e Pute, e Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 7, 'E os filhos de Cuxe: Sebá, Havilá, e Sabtá, e Raamá, e Sabtecá. E os filhos de Raamá: Sabá e Dedã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 8, 'E Cuxe gerou a Ninrode, este começou a ser poderoso na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 9, 'Este foi vigoroso caçador diante do SENHOR; pelo qual se diz: Assim como Ninrode, vigoroso caçador diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 10, 'E foi a cabeceira de seu reino Babel, e Ereque, e Acade, e Calné, na terra de Sinear.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 11, 'De esta terra saiu Assur, e edificou a Nínive, e a Reobote-Ir, e a Calá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 12, 'E a Resém entre Nínive e Calá; a qual é cidade grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 13, 'E Mizraim gerou a Ludim, e a Anamim, e a Leabim, e a Naftuim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 14, 'E a Patrusim, e a Casluim de onde saíram os filisteus, e a Caftorim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 15, 'E Canaã gerou a Sidom, seu primogênito e a Hete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 16, 'E aos jebuseus, e aos amorreus, e aos gergeseus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 17, 'E aos heveus, e aos arqueus, e aos sineus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 18, 'E aos arvadeus e aos zemareus, e aos hamateus: e depois se derramaram as famílias dos cananeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 19, 'E foi o termo dos cananeus desde Sidom, vindo a Gerar até Gaza, até entrar em Sodoma e Gomorra, Admá, e Zeboim até Lasa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 20, 'Estes são os filhos de Cam por suas famílias, por suas línguas, em suas terras, em suas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 21, 'Também lhe nasceram filhos a Sem, pai de todos os filhos de Héber, e irmão mais velho de Jafé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 22, 'E os filhos de Sem: Elão, e Assur, e Arfaxade, e Lude, e Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 23, 'E os filhos de Arã: Uz, e Hul, e Géter, e Mas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 24, 'E Arfaxade gerou a Salá, e Salá gerou a Héber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 25, 'E a Héber nasceram dois filhos: o nome de um foi Pelegue, porque em seus dias foi repartida a terra; e o nome de seu irmão, Joctã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 26, 'E Joctã gerou a Almodá, e a Salefe, e Hazarmavé, e a Jerá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 27, 'E a Hadorão, e a Uzal, e a Dicla,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 28, 'E a Obal, e a Abimael, e a Sabá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 29, 'E a Ofir, e a Havilá, e a Jobabe: todos estes foram filhos de Joctã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 30, 'E foi sua habitação desde Messa vindo de Sefar, monte à parte do oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 31, 'Estes foram os filhos de Sem por suas famílias, por suas línguas, em suas terras, em suas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 10, 32, 'Estas são as famílias de Noé por suas descendências, em suas nações; e destes foram divididas os povos na terra depois do dilúvio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 1, 'Era, então, toda a terra de uma língua e umas mesmas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 2, 'E aconteceu que, quando se partiram do oriente, acharam um vale na terra de Sinear; e ali passaram a habitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 3, 'E disseram uns aos outros: Vinde, façamos tijolos e o cozamos com fogo. E foi-lhes os tijolos em lugar de pedra, e o betume em lugar de argamassa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 4, 'E disseram: Vamos, edifiquemo-nos uma cidade e uma torre, cuja ponta chegue ao céu; e façamo-nos um nome, para que não sejamos espalhados sobre a face de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 5, 'E desceu o SENHOR para ver a cidade e a torre que edificavam os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 6, 'E disse o SENHOR: Eis que o povo é um, e todos estes têm uma língua; e começaram a agir, e nada lhes restringirá agora do que pensaram fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 7, 'Agora, pois, desçamos, e confundamos ali suas línguas, para que ninguém entenda a fala de seu companheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 8, 'Assim os espalhou o SENHOR desde ali sobre a face de toda a terra, e deixaram de edificar a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 9, 'Por isto foi chamado o nome dela Babel, porque ali confundiu o SENHOR a língua de toda a terra, e desde ali os espalhou sobre a face de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 10, 'Estas são as gerações de Sem: Sem, de idade de cem anos, gerou a Arfaxade, dois anos depois do dilúvio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 11, 'E viveu Sem, depois que gerou a Arfaxade quinhentos anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 12, 'E Arfaxade viveu trinta e cinco anos, e gerou a Salá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 13, 'E viveu Arfaxade, depois que gerou a Salá, quatrocentos e três anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 14, 'E viveu Salá trinta anos, e gerou a Héber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 15, 'E viveu Salá, depois que gerou a Héber, quatrocentos e três anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 16, 'E viveu Héber trinta e quatro anos, e gerou a Pelegue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 17, 'E viveu Héber, depois que gerou a Pelegue, quatrocentos e trinta anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 18, 'E viveu Pelegue, trinta anos, e gerou a Reú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 19, 'E viveu Pelegue, depois que gerou a Reú, duzentos e nove anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 20, 'E Reú viveu trinta e dois anos, e gerou a Serugue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 21, 'E viveu Reú, depois que gerou a Serugue, duzentos e sete anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 22, 'E viveu Serugue trinta anos, e gerou a Naor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 23, 'E viveu Serugue, depois que gerou a Naor, duzentos anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 24, 'E viveu Naor vinte e nove anos, e gerou a Terá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 25, 'E viveu Naor, depois que gerou a Terá, cento e dezenove anos, e gerou filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 26, 'E viveu Terá setenta anos, e gerou a Abrão, e a Naor, e a Harã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 27, 'Estas são as gerações de Terá: Terá gerou a Abrão, e a Naor, e a Harã; e Harã gerou a Ló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 28, 'E morreu Harã antes que seu pai Terá na terra de seu nascimento, em Ur dos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 29, 'E tomaram Abrão e Naor para si mulheres: o nome da mulher de Abrão foi Sarai, e o nome da mulher de Naor, Milca, filha de Harã, pai de Milca e de Iscá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 30, 'Mas Sarai era estéril, e não tinha filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 31, 'E tomou Terá a Abrão seu filho, e a Ló filho de Harã, filho de seu filho, e a Sarai sua nora, mulher de Abrão seu filho: e saiu com eles de Ur dos caldeus, para ir à terra de Canaã: e vieram até Harã, e assentaram ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 11, 32, 'E foram os dias de Terá duzentos e cinco anos; e morreu Terá em Harã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 1, 'O SENHOR disse a Abrão: “Sai da tua terra, e da tua parentela, e da casa de teu pai, para terra que eu te mostrarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 2, 'E farei de ti uma grande nação, e te abençoarei, e engrandecerei o teu nome, e tu serás uma bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 3, 'E abençoarei os que te abençoarem, e amaldiçoarei os que te amaldiçoarem; e em ti todas as famílias da terra serão benditas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 4, 'Assim se foi Abrão, como o SENHOR lhe dissera; e Ló foi com ele. Abrão tinha setenta e cinco anos de idade quando saiu de Harã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 5, 'E Abrão tomou a Sarai, sua mulher, e a Ló, filho de seu irmão, e todos os seus pertences que haviam ganhado, e as pessoas que eles haviam adquirido em Harã, e saíram para ir à terra de Canaã; e à terra de Canaã chegaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 6, 'E passou Abrão por aquela terra até o lugar de Siquém, até o carvalho de Moré; e os cananeus estavam então na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 7, 'E o SENHOR apareceu a Abrão, e lhe disse: À tua descendência darei esta terra. E ele edificou ali um altar ao SENHOR, que lhe havia aparecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 8, 'E passou-se dali a um monte ao oriente de Betel, e estendeu sua tenda, tendo a Betel ao ocidente e Ai ao oriente: e edificou ali altar ao SENHOR e invocou o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 9, 'E moveu Abrão dali, caminhando e indo até o Sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 10, 'E houve fome na terra, e desceu Abrão ao Egito para peregrinar ali; porque era grande a fome na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 11, 'E aconteceu que quando estava para entrar no Egito, disse a Sarai sua mulher: Eis que, agora conheço que és mulher bela à vista;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 12, 'E será que quando te houverem visto os egípcios, dirão: Sua mulher é: e matarão a mim, e a ti te preservarão a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 13, 'Agora, pois, dize que és minha irmã, para que eu vá bem por tua causa, e viva minha alma por causa de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 14, 'E aconteceu que, quando entrou Abrão no Egito, os egípcios viram a mulher que era bela em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 15, 'Viram-na também os príncipes de Faraó, e a elogiaram; e foi levada a mulher a casa de Faraó:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 16, 'E fez bem a Abrão por causa dela; e teve ovelhas, e vacas, e asnos, e servos, e criadas, e asnas e camelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 17, 'Mas o SENHOR feriu a Faraó e à sua casa com grandes pragas, por causa de Sarai mulher de Abrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 18, 'Então Faraó chamou a Abrão e lhe disse: Que é isto que fizeste comigo? Por que não me declaraste que era tua mulher?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 19, 'Por que disseste: “É minha irmã”, pondo-me em risco de tomá-la para mim por mulher? Agora, pois, eis aqui tua mulher, toma-a e vai-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 12, 20, 'Então Faraó deu ordem a seus homens acerca de Abrão; e lhe acompanharam, e à sua mulher com tudo o que tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 1, 'Subiu, pois, Abrão do Egito até o Sul de Canaã, ele e sua mulher, com tudo o que tinha, e com ele Ló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 2, 'E Abrão era riquíssimo em gado, em prata e ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 3, 'E voltou por suas jornadas da parte do Sul até Betel, até o lugar onde havia estado antes sua tenda entre Betel e Ai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 4, 'Ao lugar do altar que havia feito ali antes: e invocou ali Abrão o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 5, 'E também Ló, que andava com Abrão, tinha ovelhas, e vacas, e tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 6, 'E a terra não os podia sustentar para que habitassem juntos; porque a riqueza deles era muita, e não podiam morar num mesmo lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 7, 'E houve briga entre os pastores do gado de Abrão e os pastores do gado de Ló: e os cananeus e os ferezeus habitavam então na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 8, 'Então Abrão disse a Ló: Não haja agora briga entre mim e ti, entre meus pastores e os teus, porque somos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 9, 'Não está toda a terra diante de ti? Eu te rogo que te separes de mim. Se fores à esquerda, eu irei à direita: e se tu à direita, eu irei à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 10, 'E levantou Ló seus olhos, e viu toda a planície do Jordão, que toda ela era bem regada, antes que destruísse o SENHOR a Sodoma e a Gomorra, como o jardim do SENHOR, como a terra do Egito entrando em Zoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 11, 'Então Ló escolheu para si toda a planície do Jordão: e partiu-se Ló ao Oriente, e separaram-se um do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 12, 'Abrão assentou na terra de Canaã, e Ló assentou nas cidades da planície, e foi pondo suas tendas até Sodoma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 13, 'Mas os homens de Sodoma eram maus e pecadores para com o SENHOR em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 14, 'E o SENHOR disse a Abrão, depois que Ló se separou dele: Levanta agora teus olhos, e olha desde o lugar onde estás até o norte, e ao sul, e ao oriente e ao ocidente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 15, 'Porque toda a terra que vês, a darei a ti e à tua descendência para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 16, 'E farei tua descendência como o pó da terra: que se alguém puder contar o pó da terra, também tua descendência será contada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 17, 'Levanta-te, vai pela terra ao longo dela e à sua largura; porque a ti a tenho de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 13, 18, 'Abrão, pois, removendo sua tenda, veio e morou nos carvalhos de Manre, que é em Hebrom, e edificou ali altar ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 1, 'E aconteceu nos dias de Anrafel, rei de Sinear, Arioque, rei de Elasar, Quedorlaomer, rei de Elão, e Tidal, rei de nações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 2, 'Que estes fizeram guerra contra Bera, rei de Sodoma, e contra Birsa, rei de Gomorra, e contra Sinabe, rei de Admá, e contra Semeber, rei de Zeboim, e contra o rei de Belá, a qual é Zoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 3, 'Todos estes se juntaram no vale de Sidim, que é o mar salgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 4, 'Doze anos haviam servido a Quedorlaomer, e ao décimo terceiro ano se rebelaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 5, 'E no ano décimo quarto veio Quedorlaomer, e os reis que estavam de sua parte, e derrotaram aos refains em Asterote-Carnaim, aos zuzins em Hã, e aos emins em Savé-Quiriataim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 6, 'E aos horeus no monte de Seir, até a El-Parã, que está junto ao deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 7, 'E voltaram e vieram a En-Mispate, que é Cades, e devastaram todas as terras dos amalequitas, e também aos amorreus, que habitavam em Hazazom-Tamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 8, 'E saiu o rei de Sodoma, e o rei de Gomorra, e o rei de Admá, e o rei de Zeboim, e o rei de Belá, que é Zoar, e ordenaram contra eles batalha no vale de Sidim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 9, 'A saber, contra Quedorlaomer, rei de Elão, e Tidal, rei de nações, e Anrafel, rei de Sinear, e Arioque, rei de Elasar; quatro reis contra cinco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 10, 'E o vale de Sidim estava cheio de poços de betume: e fugiram o rei de Sodoma e o de Gomorra, e caíram ali; e os demais fugiram ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 11, 'E tomaram toda a riqueza de Sodoma e de Gomorra, e todos os seus mantimentos, e se foram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 12, 'Tomaram também Ló, filho do irmão de Abrão, que morava em Sodoma, e sua riqueza, e se foram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 13, 'E veio um dos que escaparam, e denunciou-o a Abrão o hebreu, que habitava no vale de Manre, amorreu, irmão de Escol e irmão de Aner, os quais tinham feito pacto com Abrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 14, 'E ouviu Abrão que seu irmão estava prisioneiro, e armou seus criados, os criados de sua casa, trezentos e dezoito, e seguiu-os até Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 15, 'E derramou-se sobre eles de noite ele e seus servos, e feriu-os, e foi os seguindo até Hobá, que está à esquerda de Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 16, 'E recuperou todos os bens, e também a Ló seu irmão e sua riqueza, e também as mulheres e gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 17, 'E saiu o rei de Sodoma a recebê-lo, quando voltava da derrota de Quedorlaomer e dos reis que com ele estavam, ao vale de Savé, que é o vale do Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 18, 'Então Melquisedeque, rei de Salém, tirou pão e vinho; o qual era sacerdote do Deus altíssimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 19, 'E abençoou-lhe, e disse: Bendito seja Abrão do Deus altíssimo, possuidor dos céus e da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 20, 'E bendito seja o Deus altíssimo, que entregou teus inimigos em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 21, 'Então o rei de Sodoma disse a Abrão: Dá-me as pessoas, e toma para ti a riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 22, 'E respondeu Abrão ao rei de Sodoma: Levantei minha mão ao SENHOR Deus altíssimo, possuidor dos céus e da terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 23, 'Que desde um fio até a correia de um calçado, nada tomarei de tudo o que é teu, para que não digas: Eu enriqueci a Abrão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 14, 24, 'Tirando somente o que os rapazes comeram, e a porção dos homens que foram comigo, Aner, Escol, e Manre; eles tomem a sua parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 1, 'Depois destas coisas a palavra do SENHOR veio a Abrão em visão, dizendo: Não temas, Abrão; eu sou o teu escudo; a tua recompensa será muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 2, 'Abrão respondeu: Senhor DEUS, que me darás, sendo que não tenho filho, e o herdeiro da minha casa é Eliézer de Damasco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 3, 'Disse mais Abrão: Eis que não me deste descendência, e eis que meu herdeiro é um nascido em minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 4, 'E logo a palavra do SENHOR veio a ele dizendo: Não esse não herdará de ti, mas sim o que sairá de tuas entranhas será o que de ti herdará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 5, 'E tirou-lhe fora, e disse: Olha agora aos céus, e conta as estrelas, se as podes contar. E lhe disse: Assim será tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 6, 'E creu ao SENHOR, e contou-lhe por justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 7, 'E disse-lhe: Eu sou o SENHOR, que te tirei de Ur dos caldeus, para dar-te a herdar esta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 8, 'E ele respondeu: Senhor DEUS, com que saberei que a vou herdar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 9, 'E lhe disse: Separa-me uma bezerra de três anos, e uma cabra de três anos, e um carneiro de três anos, uma rolinha também, e um pombinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 10, 'E tomou ele todas estas coisas, e partiu-as pela metade, e pôs cada metade uma em frente de outra; mas não partiu as aves.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 11, 'E desciam aves sobre os corpos mortos, e enxotava-as Abrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 12, 'Mas ao pôr do sol veio o sono a Abrão, e eis que o pavor de uma grande escuridão caiu sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 13, 'Então disse a Abrão: Tem certeza que a tua descendência será peregrina em terra que não é sua, e serão escravizados e afligidos por quatrocentos anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 14, 'Mas também a nação a quem servirão, eu julgarei; e depois disto sairão com grande riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 15, 'Tu, porém, virás aos teus pais em paz, e serás sepultado em boa velhice.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 16, 'E na quarta geração voltarão para cá; porque ainda não está completa a maldade dos amorreus até aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 17, 'E sucedeu que, depois de posto o sol, e já estando escuro, apareceu um fogo fumegando, e uma tocha de fogo que passou por entre os animais divididos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 18, 'Naquele dia fez o SENHOR um pacto com Abrão dizendo: À tua descendência darei esta terra desde o rio do Egito até o rio grande, o rio Eufrates;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 19, 'Os queneus, e os quenezeus, e os cadmoneus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 20, 'E os heteus, e os perizeus, e os refains,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 15, 21, 'E os amorreus, e os cananeus, e os girgaseus, e os jebuseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 1, 'E Sarai, mulher de Abrão não lhe dava filho: e ela tinha uma serva egípcia, que se chamava Agar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 2, 'Disse, pois, Sarai a Abrão: Já vês que o SENHOR me fez estéril: rogo-te que entres a minha serva; talvez terei filhos dela. E atendeu Abrão ao dito de Sarai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 3, 'E Sarai, mulher de Abrão, tomou a Agar sua serva egípcia, ao fim de dez anos que havia habitado Abrão na terra de Canaã, e deu-a a Abrão seu marido por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 4, 'E ele se deitou com Agar, a qual concebeu: e quando viu que havia concebido, olhava com desprezo à sua senhora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 5, 'Então Sarai disse a Abrão: Minha afronta seja sobre ti; eu pus minha serva em teus braços, e vendo-se grávida, me olha com desprezo; julgue o SENHOR entre mim e ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 6, 'E respondeu Abrão a Sarai: Eis aí tua serva em tua mão, faze com ela o que bem te parecer. E quando Sarai a afligiu, fugiu de sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 7, 'E o anjo do SENHOR a achou junto a uma fonte de água no deserto, junto à fonte que está no caminho de Sur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 8, 'E lhe disse: Agar, serva de Sarai, de onde vens tu, e para onde vais? E ela respondeu: Fujo de diante de Sarai, minha senhora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 9, 'E disse-lhe o anjo do SENHOR: Volta à tua senhora, e põe-te submissa sob a mão dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 10, 'Disse-lhe também o anjo do SENHOR: Multiplicarei tanto tua linhagem, que não será contada por causa da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 11, 'Disse-lhe ainda o anjo do SENHOR: Eis que concebeste, e darás à luz um filho, e chamarás seu nome Ismael, porque o SENHOR ouviu a tua aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 12, 'E ele será homem como um jumento selvagem; sua mão será contra todos, as mãos de todos serão contra ele, e habitará à margem de todos os seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 13, 'Então chamou o nome do SENHOR que com ela falava: Tu és o Deus da vista; porque disse: Não vi também aqui ao que me vê?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 14, 'Pelo qual chamou ao poço, Poço do Vivente que me vê. Eis que está entre Cades e Berede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 15, 'E Agar deu à luz um filho a Abrão, e Abrão chamou o nome do seu filho que Agar lhe deu à luz Ismael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 16, 16, 'E era Abrão de idade de oitenta e seis anos, quando deu à luz Agar a Ismael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 1, 'Quando Abrão tinha a idade de noventa e nove anos, o SENHOR lhe apareceu, e disse-lhe: Eu sou o Deus Todo-Poderoso; anda diante de mim, e sê íntegro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 2, 'E constituirei meu pacto entre mim e ti, e te multiplicarei em grandíssima maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 3, 'Então Abrão prostrou-se com o rosto ao chão, e Deus falou com ele, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 4, 'Quanto a mim, este é o meu pacto contigo: Serás pai de multidão de nações:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 5, 'E não se chamará mais teu nome Abrão, mas sim que será teu nome Abraão, porque te pus por pai de multidão de nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 6, 'E te multiplicarei muito em grande maneira, e te porei em nações, e reis sairão de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 7, 'E estabelecerei meu pacto entre mim e ti, e tua descendência depois de ti em suas gerações, por aliança perpétua, para ser para ti por Deus, e à tua descendência depois de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 8, 'E darei a ti, e à tua descendência depois de ti, a terra de tuas peregrinações, toda a terra de Canaã em herança perpétua; e serei o Deus deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 9, 'Disse de novo Deus a Abraão: Tu, porém, guardarás meu pacto, tu e tua descendência depois de ti por suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 10, 'Este será meu pacto, que guardareis entre mim e vós e tua descendência depois de ti: Será circuncidado todo macho dentre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 11, 'Circuncidareis, pois, a carne de vosso prepúcio, e será por sinal do pacto entre mim e vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 12, 'E de idade de oito dias será circuncidado todo macho entre vós por vossas gerações: o nascido em casa, e o comprado a dinheiro de qualquer estrangeiro, que não for de tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 13, 'Deve ser circuncidado o nascido em tua casa, e o comprado por teu dinheiro: e estará meu pacto em vossa carne para aliança perpétua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 14, 'E o macho incircunciso que não houver circuncidado a carne de seu prepúcio, aquela pessoa será exterminada de seu povo; violou meu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 15, 'Disse também Deus a Abraão: A Sarai tua mulher não a chamarás Sarai, mas Sara será seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 16, 'E a abençoarei, e também te darei dela filho; sim, a abençoarei, e virá a ser mãe de nações; dela surgirão reis de povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 17, 'Então Abraão postrou-se com o rosto ao chão, riu, e disse em seu coração: A um homem de cem anos nasceráfilho? E Sara, já de noventa anos, há de dar à luz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 18, 'E disse Abraão a Deus: Que Ismael viva diante de ti!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 19, 'E respondeu Deus: Certamente Sara tua mulher te dará à luz um filho, e chamarás seu nome Isaque; e confirmarei meu pacto com ele por aliança perpétua para sua descendência depois dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 20, 'E quanto a Ismael, também te ouvi; eis que o abençoarei, e lhe farei frutificar e multiplicar em grandíssima maneira; doze príncipes gerará, e dele farei grande nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 21, 'Mas meu pacto estabelecerei com Isaque, ao qual Sara te dará à luz por este tempo no ano seguinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 22, 'E acabou de falar com ele, e Deus subiu da presença de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 23, 'Então tomou Abraão a Ismael seu filho, e a todos os servos nascidos em sua casa, e a todos os comprados por seu dinheiro, a todo homem entre os domésticos da casa de Abraão, e circuncidou a carne do prepúcio deles naquele mesmo dia, como Deus lhe havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 24, 'Era Abraão de idade de noventa e nove anos quando circuncidou a carne de seu prepúcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 25, 'E Ismael seu filho era de treze anos quando foi circuncidada a carne de seu prepúcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 26, 'No mesmo dia foi circuncidado Abraão e Ismael seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 17, 27, 'E todos os homens de sua casa, o servo nascido em casa, e o comprado por dinheiro do estrangeiro, foram circuncidados com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 1, 'E apareceu-lhe o SENHOR nos carvalhos de Manre, estando ele sentado à porta de sua tenda no calor do dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 2, 'E levantou seus olhos e olhou, e eis que três homens que estavam junto a ele: e quando os viu, saiu correndo da porta de sua tenda a recebê-los, e inclinou-se até a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 3, 'E disse: Senhor, se agora achei favor aos teus olhos, rogo-te que não passes de teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 4, 'Que se traga agora um pouco de água, e lavai vossos pés; e recostai-vos debaixo de uma árvore,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 5, 'E trarei um bocado de pão, e confortai vosso coração; depois passareis; pois por isso passastes perto de vosso servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 6, 'Então Abraão foi depressa à tenda a Sara, e lhe disse: Toma logo três medidas de boa farinha, amassa e faz pães cozidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 7, 'E correu Abraão às vacas, e tomou um bezerro tenro e bom, e deu-o ao jovem, e deu-se este pressa a prepará-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 8, 'Tomou também manteiga e leite, e o bezerro que havia preparado, e o pôs diante deles; e ele estava junto a eles debaixo da árvore; e comeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 9, 'E lhe disseram: Onde está Sara tua mulher? E ele respondeu: Aqui na tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 10, 'Então disse: De certo voltarei a ti segundo o tempo da vida, e eis que Sara, tua mulher, terá um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 11, 'Abraão e Sara eram idosos, avançados em dias; a Sara já havia cessado o costume das mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 12, 'Riu, pois, Sara consigo mesma, dizendo: Depois que envelheci terei prazer, sendo também meu senhor já velho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 13, 'Então o SENHOR disse a Abraão: Por que Sara riu dizendo: Será verdade que darei à luz, sendo já velha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 14, 'Há para Deus alguma coisa difícil? Ao tempo assinalado voltarei a ti, segundo o tempo da vida, e Sara terá um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 15, 'Então Sara negou dizendo: Não ri; pois teve medo. Mas ele disse: Não é assim, mas riste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 16, 'E os homens se levantaram dali, e olharam até Sodoma: e Abraão ia com eles acompanhando-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 17, 'E o SENHOR disse: Encobrirei eu a Abraão o que vou a fazer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 18, 'Havendo de ser Abraão em uma nação grande e forte, e havendo de ser benditas nele todas as nações da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 19, 'Porque eu o conheci, sei que mandará a seus filhos e a sua casa depois de si, que guardem o caminho do SENHOR, fazendo justiça e juízo, para que faça vir o SENHOR sobre Abraão o que falou acerca dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 20, 'Então o SENHOR lhe disse: Porquanto o clamor de Sodoma e Gomorra se aumenta mais e mais, e o pecado deles se agravou em extremo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 21, 'Descerei agora, e verei se consumaram sua obra segundo o clamor que veio até mim; e se não, eu o saberei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 22, 'E apartaram-se dali os homens, e foram até Sodoma: mas Abraão estava ainda diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 23, 'E aproximou-se Abraão e disse: Destruirás também ao justo com o ímpio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 24, 'Talvez haja cinquenta justos dentro da cidade: destruirás também e não perdoarás ao lugar por cinquenta justos que estejam dentro dela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 25, 'Longe de ti o fazer tal, que faças morrer ao justo com o ímpio e que seja o justo tratado como o ímpio; nunca faças tal. O juiz de toda a terra, não há de fazer o que é justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 26, 'Então respondeu o SENHOR: Se achar em Sodoma cinquenta justos dentro da cidade, perdoarei a todo este lugar por causa deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 27, 'E Abraão replicou e disse: Eis que agora que comecei a falar a meu Senhor, ainda que sou pó e cinza:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 28, 'Talvez faltem de cinquenta justos cinco; destruirás por aqueles cinco toda a cidade? E disse: Não a destruirei, se achar ali quarenta e cinco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 29, 'E voltou a falar-lhe, e disse: Talvez se acharão ali quarenta. E respondeu: Não o farei por causa dos quarenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 30, 'E disse: Não se ire agora meu Senhor, se falar: talvez se achem ali trinta. E respondeu: Não o farei se achar ali trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 31, 'E disse: Eis que agora que me empreendi em falar a meu Senhor: talvez se achem ali vinte. Não a destruirei, respondeu, por causa dos vinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 32, 'E voltou a dizer: Não se ire agora meu Senhor, se falar somente uma vez: talvez se achem ali dez. Não a destruirei, respondeu, por causa dos dez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 18, 33, 'E foi-se o SENHOR, logo que acabou de falar a Abraão: e Abraão se voltou a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 1, 'Chegaram, pois, os dois anjos a Sodoma ao cair da tarde; e Ló estava sentado à porta de Sodoma. E vendo-os Ló, levantou-se a recebê-los, e inclinou-se até o chão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 2, 'E disse: Agora, pois, meus senhores, vos rogo que venhais à casa de vosso servo e vos hospedeis, e lavareis vossos pés: e pela manhã vos levantareis, e seguireis vosso caminho. E eles responderam: Não, que na praça nos ficaremos esta noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 3, 'Mas ele insistiu com eles muito, e se vieram com ele, e entraram em sua casa; e fez-lhes banquete, e cozeu pães sem levedura e comeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 4, 'E antes que se deitassem, cercaram a casa os homens da cidade, os homens de Sodoma, todo o povo junto, desde o mais jovem até o mais velho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 5, 'E chamaram a Ló, e lhe disseram: Onde estão os homens que vieram a ti esta noite? tira-os a nós, para que os conheçamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 6, 'Então Ló saiu a eles à porta, e fechou as portas atrás de si,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 7, 'E disse: Eu vos rogo, meus irmãos, que não façais tal maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 8, 'Eis aqui agora eu tenho duas filhas que não conheceram homem; eu as tirarei fora para vós, e fazei delas como bem vos parecer: somente a estes homens não façais nada, pois que vieram à sombra de meu telhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 9, 'E eles responderam: Sai daí: e acrescentaram: Veio este aqui para habitar como um estrangeiro, e haverá de levantar-se como juiz? Agora te faremos mais mal que a eles. E faziam grande violência ao homem, a Ló, e se aproximaram para romper as portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 10, 'Então os homens estenderam a mão, e meteram a Ló em casa com eles, e fecharam as portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 11, 'E aos homens que estavam à porta da casa desde o menor até o maior, feriram com cegueira; mas eles se cansavam tentando achar a porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 12, 'E disseram os homens a Ló: Tens aqui alguém mais? Genros, e teus filhos e tuas filhas, e tudo o que tens na cidade, tira-o deste lugar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 13, 'Porque vamos destruir este lugar, porquanto o clamor deles subiu demais diante do SENHOR; portanto o SENHOR nos enviou para destruí-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 14, 'Então saiu Ló, e falou a seus genros, os que haviam de se casar com suas filhas, e lhes disse: Levantai-vos, saí deste lugar; porque o SENHOR vai destruir esta cidade. Mas pareceu a seus genros como que se ridicularizava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 15, 'E ao raiar a alva, os anjos davam pressa a Ló, dizendo: Levanta-te, toma tua mulher, e teus dois filhas que se acham aqui, para que não pereças no castigo da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 16, 'E demorando-se ele, os homens pegaram por sua mão, e pela mão de sua mulher, e pelas mãos de suas duas filhas segundo a misericórdia do SENHOR para com ele; e o tiraram, e o puseram fora da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 17, 'E foi que quando os tirou fora, disse: Escapa por tua vida; não olhes atrás de ti, nem pares toda esta planície; escapa ao monte, não seja que pereças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 18, 'E Ló lhes disse: Não, eu vos rogo, senhores meus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 19, 'Eis que agora achou teu servo favor em teus olhos, e engrandeceste tua misericórdia que fizeste comigo dando-me a vida; mas eu não poderei escapar ao monte, não seja caso que me alcance o mal e morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 20, 'Eis que agora esta cidade está próxima para fugir ali, a qual é pequena; escaparei agora ali, (não é ela pequena?) e viverá minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 21, 'E lhe respondeu: Eis que recebi também tua súplica sobre isto, e não destruirei a cidade de que falaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 22, 'Apressa-te, escapa-te ali; porque nada poderei fazer até que ali tenhas chegado. Por isto foi chamado o nome da cidade, Zoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 23, 'O sol saía sobre a terra, quando Ló chegou a Zoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 24, 'Então choveu o SENHOR sobre Sodoma e sobre Gomorra enxofre e fogo da parte do SENHOR desde os céus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 25, 'E destruiu as cidades, e toda aquela planície, com todos os moradores daquelas cidades, e o fruto da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 26, 'Então a mulher de Ló olhou atrás, às costas dele, e se tornou estátua de sai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 27, 'E subiu Abraão pela manhã ao lugar onde havia estado diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 28, 'E olhou até Sodoma e Gomorra, e até toda a terra daquela planície olhou; e eis que a fumaça subia da terra como a fumaça de um forno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 29, 'Assim foi que, quando destruiu Deus as cidades da planície, lembrou-se Deus de Abraão, e enviou fora a Ló do meio da destruição, ao assolar as cidades onde Ló estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 30, 'Porém Ló subiu de Zoar, e assentou no monte, e suas duas filhas com ele; porque teve medo de ficar em Zoar, e se abrigou em uma caverna ele e suas duas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 31, 'Então a maior disse à menor: Nosso pai é velho, e não resta homem na terra que entre a nós conforme o costume de toda a terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 32, 'Vem, demos a beber vinho a nosso pai, e durmamos com ele, e conservaremos de nosso pai geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 33, 'E deram a beber vinho a seu pai aquela noite: e entrou a maior, e dormiu com seu pai; mas ele não sentiu quando se deitou com ela nem quando se levantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 34, 'O dia seguinte disse a maior à menor: Eis que eu dormi a noite passada com meu pai; demos a ele de beber vinho também esta noite, e entra e dorme com ele, para que conservemos de nosso pai geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 35, 'E deram a beber vinho a seu pai também aquela noite: e levantou-se a menor, e dormiu com ele; mas não conseguiu perceber quando se deitou com ela, nem quando se levantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 36, 'E conceberam as duas filhas de Ló, de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 37, 'E deu à luz a maior um filho, e chamou seu nome Moabe, o qual é pai dos moabitas até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 19, 38, 'A menor também deu à luz um filho, e chamou seu nome Ben-Ami, o qual é pai dos amonitas até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 1, 'De ali partiu Abraão à terra do Sul, e assentou entre Cades e Sur, e habitou como peregrino em Gerar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 2, 'E disse Abraão de Sara sua mulher: É minha irmã. E Abimeleque, rei de Gerar, enviou e tomou a Sara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 3, 'Porém Deus veio a Abimeleque em sonhos de noite, e lhe disse: Eis que morto és por causa da mulher que tomaste, a qual é casada com marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 4, 'Mas Abimeleque não havia chegado a ela, e disse: Senhor, matarás também a gente justa?')
